"Урок 9. Мудрость народа": "Дарс 9. Хиради халқ",
"Мудрость народа": "Хиради халқ",
"Различать жырау и акынов, называть Жаяу Мусу и объяснять, о чём его песня «Ақ сиса».": "Жыраву ва ақинҳоро фарқ кардан, Жаяу Мусаро номбар кардан ва фаҳмонидан, ки суруди ӯ «Ақ сиса» дар бораи чист.",
"Песни во все времена отражали жизнь народа и его мудрость. По-казахски это «халық даналығы», по-английски — wisdom of the people.": "Сурудҳо дар ҳама давру замон зиндагии халқ ва хиради ӯро инъикос мекарданд. Ба қазоқӣ ин «халық даналығы», ба забони англисӣ — wisdom of the people аст.",
"Песни о природе": "Сурудҳо дар бораи табиат",
"Кочуя по степи, казахи воспевали природу и сравнивали её величие с храбростью и мужеством предков. Они слушали сказания (эпос, жыр) под звуки кобыза или домбры.": "Қазоқҳо дар даштҳо кӯч баста, табиатро васф мекарданд ва бузургии онро бо шуҷоату диловарии аҷдодон муқоиса менамуданд. Онҳо афсонаҳоро (достон, жыр) бо садои қубуз ё домбра гӯш мекарданд.",
"Жырау": "Жыраву",
"Жырау — высокопоставленный человек: мог быть предводителем племён, полководцем, важным сановником. Его главная задача — служить государству, хану и народу.": "Жыраву — шахси баландмартаба: метавонист сардори қабилаҳо, сарлашкар, аъёни муҳим бошад. Вазифаи асосии ӯ хизмат ба давлат, хон ва халқ аст.",
"Акын": "Ақин",
