"Жаяу Муса и «Ақ сиса»": "Жаяу Муса ва «Ақ сиса»",
"Жаяу Муса (Муса Байжанулы, 1835–1929) — казахский народный композитор и акын. Его самая знаменитая песня «Ақ сиса» осуждает подлые поступки богачей.": "Жаяу Муса (Муса Байжанулы, 1835–1929) — оҳангсози халқӣ ва ақини қазоқ. Машҳуртарин суруди ӯ «Ақ сиса» корҳои пасти сарватмандонро маҳкум мекунад.",
