"Верно. Богач отобрал у Мусы единственного хорошего коня.": "Дуруст. Сарватманд ягона аспи хуби Мусоро гирифт.",
"Неверно. Это песня Мусы Байжанулы.": "Нодуруст. Ин суруди Муса Байжанулы аст.",
"Верно. Так они любовались закатами и восходами в степи.": "Дуруст. Ҳамин тавр онҳо ғуруб ва тулӯи офтобро дар дашт тамошо мекарданд.",
