"Радость народа": "Шодии халқ",
"Объяснять, кто такие сал и сері, и называть знаменитых композиторов Биржан-сала и Ахана сері.": "Фаҳмонидан, ки сал ва серӣ кистанд, ва оҳангсозони машҳур Биржан-сал ва Аҳан сериро номбар кардан.",
"Сал и сері": "Сал ва серӣ",
"Сал и сері — представители древней поэтической культуры. Их творчество — своеобразная часть культурного наследия Казахстана.": "Сал ва серӣ — намояндагони фарҳанги қадимаи шеърӣ. Эҷодиёти онҳо қисми хоси мероси фарҳангии Қазоқистон аст.",
"Радость и воспитание": "Шодӣ ва тарбия",
"Сал и сері представляли интересы молодёжи и развлекали её. Но они ещё и воспитывали: учили основам степного этикета и правилам поведения.": "Сал ва серӣ манфиатҳои ҷавононро намояндагӣ мекарданд ва онҳоро хурсанд менамуданд. Аммо онҳо боз тарбия ҳам мекарданд: асосҳои одоби даштӣ ва қоидаҳои рафторро меомӯзонданд.",
"Биржан-сал": "Биржан-сал",
"Биржан-сал Кожагулулы (1834–1897) — казахский акын и народно-профессиональный певец-композитор. Он известен благодаря айтысу с Сарой Тастанбек-кызы.": "Биржан-сал Кожагулулы (1834–1897) — ақин ва овозхон-оҳангсози халқӣ-касбии қазоқ. Ӯ бо айтыс бо Сара Тастанбек-қизи маъруф шудааст.",
"Ахан сері": "Аҳан серӣ",
"Ахан сері Корамсаулы (1843–1913) — народный поэт-акын, певец и композитор. Слово «сері» значит «поэт-песенник».": "Аҳан серӣ Корамсаулы (1843–1913) — шоири халқӣ-ақин, овозхон ва оҳангсоз. Калимаи «серӣ» маънои «шоири сурудсаро»-ро дорад.",
"Чем отличаются": "Чӣ тафовут доранд",
"Сал — певец-композитор и импровизатор, особо талантливый человек. Сері тоже певец и импровизатор, но ещё и прекрасный охотник, умеющий тренировать ловчих птиц.": "Сал — овозхон-оҳангсоз ва бедоҳасароянда, шахси хеле боистеъдод. Серӣ низ овозхон ва бедоҳасароянда аст, аммо боз шикорчии хуб ҳам ҳаст, ки мурғони шикориро омӯзонида метавонад.",
"Разложи: сал, сері или оба": "Ҷудо кун: сал, серӣ ё ҳардуро",
