"Урок 11. Память народа": "Дарс 11. Хотираи халқ",
"Память народа": "Хотираи халқ",
"Объяснять, что такое культурное наследие и пение a cappella, и называть, что создал Абай Кунанбаев.": "Фаҳмонидан, ки мероси фарҳангӣ ва суруд a cappella чист, ва номбар кардани он чизе, ки Абай Кунанбаев офаридааст.",
"Культурное наследие": "Мероси фарҳангӣ",
"Наследие — это то, что народ бережно хранит и передаёт из поколения в поколение. По-казахски — ата мұра, по-английски — heritage.": "Мерос — ин чизест, ки халқ бо эҳтиёт нигоҳ медорад ва аз насл ба насл мегузаронад. Ба қазоқӣ — ата мӯра, ба забони англисӣ — heritage.",
"Абай Кунанбаев": "Абай Кунанбаев",
"Абай (1845–1904) — казахский поэт, композитор и мыслитель, основоположник казахской письменной литературы. Его песни народ хранит как великое сокровище.": "Абай (1845–1904) — шоир, оҳангсоз ва мутафаккири қазоқ, асосгузори адабиёти хаттии қазоқ. Сурудҳои ӯро халқ ҳамчун ганҷи бузург нигоҳ медорад.",
"Имя Абай": "Номи Абай",
"Настоящее имя — Ибрагим. Прозвище Абай дала ему бабушка Зере, оно означает «внимательный», «осторожный» и осталось с ним на всю жизнь.": "Номи аслӣ — Иброҳим. Лақаби Абайро набераи Зере кампир додааст, он маънои «диққатнок», «эҳтиёткор»-ро дорад ва то охири умр бо ӯ монд.",
"Пение a cappella": "Суруди a cappella",
"A cappella — это пение без инструментального сопровождения. Звучат только голоса. Сравни: одну и ту же песню можно услышать с аккомпанементом и без него.": "A cappella — ин суруд бе ҳамроҳии асбобӣ аст. Танҳо овозҳо садо медиҳанд. Муқоиса кун: ҳамон як сурударо ҳам бо ҳамроҳӣ ва ҳам бе он шунидан мумкин аст.",
"Песня, ставшая народной": "Суруде, ки халқӣ шуд",
"Гёте написал «Ночную песню странника», Лермонтов переложил её на русский язык, а спустя полвека Абай передал её содержание на казахском. Так появилась песня «Қараңғы түнде тау қалғып».": "Гёте «Суруди шабонаи сайёҳ»-ро навишт, Лермонтов онро ба русӣ гардонд ва пас аз ним аср Абай мазмуни онро ба қазоқӣ расонид. Ҳамин тавр суруди «Қарангғы тӯнде тау қалғып» пайдо шуд.",
"Кто что сделал?": "Кӣ чӣ кор кардааст?",
"Расставь карточки по трём поэтам: кому принадлежит каждый факт.": "Кортҳоро ба се шоир тақсим кун: ҳар факт ба кӣ тааллуқ дорад.",
