"Объяснять, что такое симфонический кюй, и называть композитора Е. Рахмадиева и его кюй «Дайрабай».": "Фаҳмонидан, ки куйи симфонӣ чист, ва оҳангсоз Е. Раҳмадиев ва куйи ӯ «Дайрабай»-ро номбар кардан.",
"Домбра была бессменным спутником акынов, жырау и жыршы. Это главный инструмент народных кюев.": "Домбра ҳамсафари доимии ақинҳо, жырауҳо ва жыршиҳо буд. Ин асбоби асосии куйҳои халқӣ аст.",
"Кюй": "Куй",
"Большинство известных кюев написаны именно для домбры. Их создали наши предки.": "Аксари куйҳои маъруф маҳз барои домбра навишта шудаанд. Онҳоро аҷдодони мо эҷод кардаанд.",
"Современные композиторы не только сохраняют музыку предков, но и создают новую. Они берут всё лучшее из музыкального наследия народа.": "Оҳангсозони имрӯза на танҳо мусиқии аҷдодонро нигоҳ медоранд, балки мусиқии нав ҳам эҷод мекунанд. Онҳо беҳтарини мероси мусиқии халқро мегиранд.",
"Симфонический кюй": "Куйи симфонӣ",
"Это авторское сочинение современного композитора на основе народного кюя. Он не просто переложен для оркестра.": "Ин асари муаллифии оҳангсози имрӯза дар асоси куйи халқӣ аст. Он танҳо барои оркестр дигар карда нашудааст.",
