"Неверно. Они и сохраняют музыку предков, и создают новую.": "Нодуруст. Онҳо ҳам мусиқии аҷдодонро нигоҳ медоранд ва ҳам мусиқии нав эҷод мекунанд.",
"Неверно. Автор песни — Е. Обухова.": "Нодуруст. Муаллифи суруд — Е. Обухова.",
"Верно. Его сочиняют с оркестровкой, поэтому звучит оркестр.": "Дуруст. Онро бо оркестровка эҷод мекунанд, барои ҳамин оркестр садо медиҳад.",
