"Урок 13. Музыкальные вариации": "Дарс 13. Вариатсияҳои мусиқӣ",
"Музыкальные вариации": "Вариатсияҳои мусиқӣ",
"Объяснять, что такое вариация, и различать профессии композитора и аранжировщика.": "Фаҳмонед, ки вариатсия чист ва касбҳои композитор ва аранжировкачиро фарқ кунед.",
"Композитор сочиняет музыку: придумывает образы, развивает и дополняет их. Он пишет и для голоса, и для инструментов.": "Композитор мусиқӣ эҷод мекунад: симоҳо меандешад, онҳоро инкишоф медиҳад ва пурра мекунад. Вай ҳам барои овоз ва ҳам барои асбобҳо менависад.",
"Что пишет композитор": "Композитор чӣ менависад",
"Композиторы создают разные произведения: от оперы до популярных песен. Они сочиняют вступление, главный мотив и завершение.": "Композиторҳо асарҳои гуногун эҷод мекунанд: аз опера то сурудҳои машҳур. Онҳо муқаддима, оҳанги асосӣ ва хотимаро эҷод мекунанд.",
"Аранжировщик": "Аранжировкачӣ",
"Аранжировщик «оформляет» музыкальные композиции. Он перекладывает музыку под нужные инструменты или голос.": "Аранжировкачӣ таркибҳои мусиқиро «оро медиҳад». Вай мусиқиро барои асбобҳо ё овози лозимӣ мувофиқ мекунад.",
"Где нужен аранжировщик": "Аранжировкачӣ дар куҷо лозим аст",
"Эта профессия востребована в шоу-бизнесе, индустрии развлечений и кино. Для работы аранжировщики используют специальные программы, которые воспроизводят звучание разных инструментов.": "Ин касб дар шоу-бизнес, соҳаи фароғат ва кино зиёд лозим аст. Аранжировкачиён барои кор барномаҳои махсусро истифода мебаранд, ки садои асбобҳои гуногунро такрор мекунанд.",
"Вариация": "Вариатсия",
"Мелодия видоизменяется, но не теряет своих характерных очертаний. Такой приём в музыке называется вариация.": "Оҳанг тағйир меёбад, вале хатҳои хоси худро гум намекунад. Чунин усул дар мусиқӣ вариатсия номида мешавад.",
