"Неверно. Мелодия не теряет своих характерных очертаний.": "Нодуруст. Оҳанг хатҳои хоси худро гум намекунад.",
"Верно. Также в шоу-бизнесе и индустрии развлечений.": "Дуруст. Инчунин дар шоу-бизнес ва соҳаи фароғат.",
"Неверно. Он создаёт и оперы, и инструментальные произведения.": "Нодуруст. Вай ҳам операҳо ва ҳам асарҳои сазӣ эҷод мекунад.",
"Верно. Они воспроизводят звучание разных инструментов.": "Дуруст. Онҳо садои асбобҳои гуногунро такрор мекунанд.",
"Неверно. Аранжировщик может переложить её и для оркестра.": "Нодуруст. Аранжировкачӣ метавонад онро барои оркестр ҳам мувофиқ кунад.",
"Верно. Он входит в число величайших композиторов.": "Дуруст. Вай аз ҷумлаи бузургтарин композиторҳо аст.",
"Неверно. Часто создатели музыки сами исполняют свои песни.": "Нодуруст. Эҷодкорони мусиқӣ аксар вақт сурудҳои худро худашон иҷро мекунанд.",
"Верно. Так старая музыка звучит по-новому.": "Дуруст. Ба ин тариқ мусиқии кӯҳна ба таври нав садо медиҳад.",
"Найди: Композитор": "Ёбед: Оҳангсоз",
"Найди: Аранжировщик": "Ёбед: Аранжировкачӣ",
"Найди: Родился до 1800 года": "Ёбед: Пеш аз соли 1800 таваллуд шудааст",
"Найди: Родился после 1800 года": "Ёбед: Баъд аз соли 1800 таваллуд шудааст",
"Урок 14. Голоса и подголоски": "Дарс 14. Овозҳо ва зеровозҳо",
"Голоса и подголоски": "Овозҳо ва зеровозҳо",
"Объяснять, что такое многоголосие, подголосок и тембр, и называть правила бережного отношения к голосу.": "Фаҳмонед, ки бисёровозӣ, зеровоз ва тембр чист ва қоидаҳои эҳтиёт кардани овозро номбар кунед.",
"Многоголосие": "Бисёровозӣ",
"Когда поют сразу несколько голосов, получается многоголосие. Его ещё называют полифонией (по-казахски «көпдауысты», по-английски polyphony).": "Вақте ки якбора якчанд овоз месарояд, бисёровозӣ ба вуҷуд меояд. Онро полифония низ меноманд (бо қазоқӣ «кӯпдауысты», бо англисӣ polyphony).",
"Голос неповторим": "Овоз тақлидшаванда нест",
"Голос каждого человека звучит по-своему. Один голос низкий и сильный, другой тёплый и средний, третий высокий и лёгкий.": "Овози ҳар шахс ба тарзи худ садо медиҳад. Як овоз паст ва қавӣ, дигаре гарм ва миёна, сеюмӣ баланд ва сабук аст.",
"Подголосок": "Зеровоз",
"Голос, который вторит основному голосу, то есть главной мелодии, называют подголоском. Он добавляет хору дополнительные краски.": "Овозеро, ки овози асосиро пайравӣ мекунад, яъне оҳанги асосиро, зеровоз меноманд. Он ба хор рангҳои иловагӣ меорад.",
"Тембр": "Тембр",
"Индивидуальную окраску и яркость голоса называют тембром. Бывает тембр резкий и мягкий, грудной, головной и смешанный.": "Ранг ва равшании инфиродии овозро тембр меноманд. Тембри тез ва нарм, синавӣ, сарӣ ва омехта вуҷуд дорад.",
"Береги голос": "Овози худро эҳтиёт кун",
"Голос — уникальный инструмент. Не кричи и не шепчи, пей воду комнатной температуры, а перед пением не пей апельсиновый сок и молочные напитки.": "Овоз — асбоби беназир аст. Дод назан ва пичир-пичир накун, оби ҳарорати хонагӣ нӯш, ва пеш аз сурудхонӣ шарбати афлесун ва нӯшокиҳои ширӣ нанӯш.",
"Забота о голосе": "Ғамхорӣ дар бораи овоз",
"Реши, что помогает голосу, а что ему вредит.": "Ҳал кун, ки чӣ ба овоз кӯмак мекунад ва чӣ ба он зарар мерасонад.",
"Это полезно или вредно для голоса?": "Ин барои овоз муфид аст ё зарарнок?",
"Полезно для голоса": "Барои овоз муфид",
"Вредно для голоса": "Барои овоз зарарнок",
"Говорить обычным голосом": "Бо овози оддӣ гап задан",
"Спокойная речь не напрягает связки.": "Гуфтугӯи ором пардаҳои овозро намекашад.",
"Пить воду комнатной температуры": "Оби ҳарорати хонагӣ нӯшидан",
"Не слишком холодная и не горячая.": "На хеле хунук ва на гарм.",
"Увлажнять горло тёплой водой во время пения": "Ҳангоми сурудхонӣ гулӯро бо оби гарм тар кардан",
"Горлу нужна влага.": "Гулӯ ба нам ниёз дорад.",
"Передавать эмоции песни": "Эҳсосоти сурудро расондан",
"Нужно прочувствовать, о чём песня.": "Бояд ҳис кард, ки суруд дар бораи чист.",
