"Самый главный музыкант": "Мусиқинавози асосӣ",
"Объяснять, какая задача стоит перед дирижёром и почему его называют «главным» музыкантом.": "Фаҳмонед, ки дирижёр чӣ вазифа дорад ва чаро ӯро мусиқинавози «асосӣ» меноманд.",
"Кто такой дирижёр": "Дирижёр кист",
"Дирижёр управляет хором или оркестром. Его называют самым главным музыкантом в команде музыкантов.": "Дирижёр хор ё оркестрро идора мекунад. Ӯро дар гурӯҳи мусиқинавозон мусиқинавози аз ҳама асосӣ меноманд.",
"Хор и оркестр — команда": "Хор ва оркестр — гурӯҳ",
"Хор и оркестр похожи на спортивную команду: все вместе работают над общим делом. В любой команде нужен лидер.": "Хор ва оркестр ба дастаи варзишӣ монанданд: ҳама якҷоя дар болои кори умумӣ кор мекунанд. Дар ҳар гурӯҳ сарвар лозим аст.",
"Главная задача дирижёра": "Вазифаи асосии дирижёр",
"Дирижёр должен увлечь музыкантов и повести их за собой. От его мастерства зависит, как звучит хор или оркестр.": "Дирижёр бояд мусиқинавозонро ба худ ҷалб кунад ва онҳоро пеш барад. Аз маҳорати ӯ вобаста аст, ки хор ё оркестр чӣ гуна садо медиҳад.",
"Дирижёрская палочка": "Чӯбчаи дирижёрӣ",
"Достаточно взмаха дирижёрской палочки — и музыканты становятся единым целым. Они чувствуют даже малейшие нюансы настроения дирижёра.": "Як ҷунбонидани чӯбчаи дирижёрӣ кифоя аст — ва мусиқинавозон ба як воҳиди ягона табдил меёбанд. Онҳо ҳатто хурдтарин нозукиҳои кайфияти дирижёрро ҳис мекунанд.",
"Песня «Атамекен»": "Суруди «Атамекен»",
"Музыку к песне «Атамекен» написал Е. Хасангалиев, слова — К. Мырзалиев. Эта песня часто звучит и в вокальной, и в инструментальной обработках.": "Мусиқии суруди «Атамекен»-ро Е. Хасангалиев навиштааст, калимаҳояшро К. Мирзалиев. Ин суруд аксар вақт ҳам дар коркарди вокалӣ ва ҳам дар коркарди сазӣ садо медиҳад.",
"Кто что делает?": "Кӣ чӣ кор мекунад?",
"Разложи карточки: что относится к дирижёру, к хору, а что к оркестру.": "Кортҳоро ҷудо кун: чӣ ба дирижёр, чӣ ба хор ва чӣ ба оркестр тааллуқ дорад.",
