"В жизни опаздывать на урок плохо. А в каноне «опоздание» голосов — это красиво и задумано композитором.": "Дар зиндагӣ ба дарс дер мондан бад аст. Аммо дар канон «дер мондани» овозҳо зебост ва аз ҷониби композитор пешбинӣ шудааст.",
"Самый известный канон": "Машҳуртарин канон",
"Самый известный пример канона — французская песенка «Братец Яков». Её можно петь и на других языках, например на английском.": "Машҳуртарин мисоли канон — суруди фаронсавии «Бародар Яков» аст. Онро ба забонҳои дигар, масалан ба англисӣ, низ сароидан мумкин аст.",
"Шанкобыз и варган": "Шанкобыз ва варган",
"Канон можно исполнять и на музыкальных инструментах. Шанкобыз и варган — родственные инструменты, но варган — это не шанкобыз, а его ближайший родственник.": "Канонро бо асбобҳои мусиқӣ низ иҷро кардан мумкин аст. Шанкобыз ва варган асбобҳои хешованданд, аммо варган шанкобыз нест, балки наздиктарин хешованди он аст.",
"Роли на празднике": "Нақшҳо дар ид",
"Чтобы подготовить выступление на новогоднем празднике, нужно выбрать роль: дирижёр, певец или музыкант, играющий на инструменте. Ещё важно продумать исполнительский план.": "Барои тайёр кардани баромад дар иди солинав бояд нақшро интихоб кард: дирижёр, сароянда ё мусиқинавоз, ки бо асбоб менавозад. Инчунин муҳим аст, ки нақшаи иҷроро андеша кунед.",
"Выбери роль на празднике": "Нақшро дар ид интихоб кун",
"Подумай, чем занимается каждый участник выступления, и разложи карточки по ролям.": "Фикр кун, ки ҳар иштирокчии баромад чӣ кор мекунад, ва кортҳоро аз рӯи нақшҳо ҷудо кун.",
"Какая это роль?": "Ин кадом нақш аст?",
"Музыкант на инструменте": "Мусиқинавоз бо асбоб",
"Управляет исполнением": "Иҷроро идора мекунад",
"Он руководит всеми участниками.": "Вай ҳамаи иштирокчиёнро роҳбарӣ мекунад.",
"Показывает, когда должен вступить каждый голос": "Нишон медиҳад, ки ҳар овоз кай бояд ворид шавад",
"Он подаёт знаки исполнителям.": "Вай ба иҷрокунандагон ишора медиҳад.",
"Стоит перед исполнителями и ведёт их за собой": "Дар назди иҷрокунандагон меистад ва онҳоро пеш мебарад",
"Он не поёт и не играет, а направляет.": "Вай намесарояд ва наменовозад, балки роҳнамоӣ мекунад.",
