"Мәдениет деген не?": "Фарҳанг чист?",
"Адамзаттың ақыл-ойымен және қолымен жасалған құндылықтардың бәрі мәдениет деп аталады. Мысалы: әдебиет, қолөнер, бейнелеу өнері, сәулет өнері және музыка.": "Ҳамаи арзишҳое, ки бо ақл ва дасти инсон сохта шудаанд, фарҳанг номида мешаванд. Масалан: адабиёт, ҳунармандӣ, санъати тасвирӣ, меъморӣ ва мусиқӣ.",
"Мәдени мұра": "Мероси фарҳангӣ",
"Осы өнерлердің барлық туындылары ата-бабамыздан келе жатқан мәдени мұраға жатады. Домбыра мен күй де — біздің асыл мұрамыз.": "Ҳамаи асарҳои ин навъи санъат ба мероси фарҳангии аз ниёгонамон боқимонда дохил мешаванд. Домбира ва куй низ мероси гаронбаҳои мост.",
"«Ақсақ құлан» күйі": "Куйи «Ақсақ қулан»",
"Бұл — қазақтың халық күйі, аңыз күй. Ол халық арасына кең таралған асыл мұрамыздың бірі.": "Ин куйи халқии қазоқӣ ва куйи афсонавӣ аст. Он яке аз меросҳои гаронбаҳои мост, ки дар миёни мардум васеъ паҳн шудааст.",
"Күйдің аңызы": "Афсонаи куй",
"Аңшылыққа шыққан хан баласы қайтыс болады. Хан қайғылы хабарды айтқан адамның көмейіне қорғасын құймақ болады. Сонда бір қарт домбырашы күймен хабарды жеткізеді.": "Писари хон ҳангоми шикор вафот мекунад. Хон мехоҳад ба коми касе, ки хабари ғамангезро расонад, сурб резад. Он гоҳ домбирачии солхӯрда хабарро бо куй мерасонад.",
"Домбыраға құрмет": "Эҳтиром ба домбира",
"2018 жылдан бастап шілде айының бірінші жексенбісі — «Домбыра күні» мерекесі. 2014 жылы ЮНЕСКО шешімімен домбырамен орындалатын күй өнері адамзаттың бүкіләлемдік құндылықтарына енді.": "Аз соли 2018 якшанбеи аввали моҳи июл иди «Рӯзи домбира» аст. Дар соли 2014 бо қарори ЮНЕСКО санъати куйи бо домбира иҷрошаванда ба арзишҳои умумиҷаҳонии башарият дохил шуд.",
"Күй мен әнді ажырат": "Куй ва сурудро фарқ кун",
"Әр карточканы дұрыс топқа қой: «Ақсақ құлан» күйіне ме, әлде «Домбыра болып сөйледім» әніне ме?": "Ҳар корточкаро ба гурӯҳи дуруст гузор: ба куйи «Ақсақ қулан» ё ба суруди «Домбира болип сӯйледим»?",
