"Көне қобыз сарыны": "Садои қадимаи қобиз",
"Қобыз аспабының жасалуын сипаттау, Қорқыт ата мен Ықылас Дүкенұлы туралы айту.": "Тавсиф кардани сохтани асбоби қобиз, нақл кардан дар бораи Қурқут ота ва Иқлос Дукенули.",
"Қобыз – көне аспап": "Қобиз — асбоби қадима",
"Қобыз – ұлттық мәдени мұрамыздағы ерекше орны бар аспап. Оны скрипка, виолончель сияқты еуропалық ыспалы аспаптардың арғы атасы деп санайды.": "Қобиз — асбобест, ки дар мероси фарҳангии миллии мо ҷои хоса дорад. Онро бобои асбобҳои аврупоии камончагии мисли скрипка ва виолончел ҳисоб мекунанд.",
"Қобыздың жасалуы": "Сохтани қобиз",
"Шеберлер қобыздың жасалуына аса зор мән берген. Шанақты ағаштан ойып, үңгіп жасайды, ал оның бетіне көн қаптайды.": "Усторон ба сохтани қобиз аҳамияти бисёр калон додаанд. Косаро аз чӯб кофта, ковок месозанд ва рӯи онро бо пӯст мепӯшонанд.",
"Қорқыт ата": "Қурқут ота",
"Қобыз аспабы Қорқыт ата есімімен қатар аталады. Ол – ел бірлігін нығайтқан кемеңгер қайраткер, ғұлама ойшыл, күйші, жырау.": "Асбоби қобиз бо номи Қурқут ота ёд мешавад. Ӯ — арбоби доно, ки ягонагии мардумро мустаҳкам кардааст, мутафаккири бузург, куйчӣ ва жирау.",
"ЮНЕСКО тізімінде": "Дар феҳристи ЮНЕСКО",
"Қорқыттың музыкалық мұрасы, эпосы және халық ақындары 2018 жылы ЮНЕСКО-ның мәдени мұралар тізіміне енгізілді.": "Мероси мусиқӣ, эпос ва шоирони халқии Қурқут дар соли 2018 ба феҳристи меросҳои фарҳангии ЮНЕСКО дохил карда шуд.",
"Ықылас Дүкенұлы": "Иқлос Дукенули",
"Ықылас Дүкенұлы (1843–1916) – композитор, күйші, қобызшы. Ол Жезқазған өңірінде дүниеге келген, қобыз өнерін заманымызға жеткізген ұлы күйші.": "Иқлос Дукенули (1843–1916) — оҳангсоз, куйчӣ ва қобизнавоз. Ӯ дар ноҳияи Жезқазған таваллуд шуда, куйчии бузургест, ки санъати қобизро то замони мо расонидааст.",
