"Бұрыс. Ол 1843–1916 жылдары өмір сүрген.": "Нодуруст. Ӯ дар солҳои 1843–1916 зиндагӣ кардааст.",
"Дұрыс. Дұрыс, бұл 2018 жылы болды.": "Дуруст. Дуруст, ин дар соли 2018 буд.",
"Бұрыс. Ықылас – қобызшы.": "Нодуруст. Иқлос — қобизнавоз.",
