"11-сабақ. Атадан қалған жауһар жыр": "Дарс 11. Ёдгории гаронбаҳои аз ниёгон мондаи жир",
"Атадан қалған жауһар жыр": "Ёдгории гаронбаҳои аз ниёгон мондаи жир",
"Жыр, жырау, жыршы ұғымдарын түсіндіру және жыр батырлары мен Бұқар жырауды атау": "Фаҳмонидани мафҳумҳои жир, жирау, жирши ва номбар кардани қаҳрамонони жир ва Бухар жирау",
"Жыр деген не?": "Жир чист?",
"Халық өмірінен алынған оқиғалы, ұзақ өлеңдерді «жыр» деп атайды. Батырлар жыры көп халықта сақталған.": "Шеърҳои воқеадор ва дарозе, ки аз зиндагии мардум гирифта шудаанд, «жир» номида мешаванд. Жирҳои қаҳрамонӣ дар назди бисёр халқҳо нигоҳ дошта шудаанд.",
"Батырлар кім?": "Паҳлавонон кистанд?",
"Ертеде халық елін-жерін қорғайтын, суға салса батпайтын, отқа салса жанбайтын хас батырларды аңсаған. Алпамыс, Қобыланды, Ер Тарғын, Қамбар сияқты батырлар осылай шыққан.": "Замоне мардум паҳлавонони ҳақиқиро орзу мекарданд, ки диёру халқашонро ҳимоя кунанд, дар об ғарқ нашаванд ва дар оташ насӯзанд. Паҳлавонҳои мисли Алпамис, Қобиланди, Ер Тарғин, Қамбар ҳамин тавр пайдо шудаанд.",
"Жыр қалай айтылады?": "Жир чӣ тавр хонда мешавад?",
"Батырлардың ерліктерін домбыраға, қобызға қосып айтқан. Кейде аспапсыз-ақ жыр, терме түрінде екпінді әуенмен баяндаған.": "Мардонагии паҳлавононро бо домбира ва қобиз ҳамроҳ хондаанд. Гоҳо бе асбоб ҳам дар шакли жир ва терме бо оҳанги шадид баён кардаанд.",
"Бір ұғым — үш атау": "Як мафҳум — се ном",
"Жырды гректер «эпос» дейді, қазақтар «жыр», ал қырғыздар «ыр» дейді. Қазақтың жыр-дастандары көбіне 7-8 буынмен жазылады.": "Юнониҳо жирро «эпос» мегӯянд, қазоқҳо «жир», қирғизҳо бошанд «ир» мегӯянд. Жир-достонҳои қазоқӣ аксаран бо 7–8 ҳиҷо навишта мешаванд.",
"Жырау мен жыршы": "Жирау ва жирши",
"Жырды шығарушы және орындаушы адамды жырау деп атайды. Жыршы дайын жырды орындайды. Бұқар жырау Қалқаманұлы — Абылай ханның ақылшы-кеңесшісі.": "Шахсеро, ки жирро месозад ва иҷро мекунад, жирау меноманд. Жирши жири тайёрро иҷро мекунад. Бухар жирау Қалқаманули — маслиҳатчии Абулай хон.",
