"Естай Беркінбайұлын және «Құсни-Қорлан», «Қоғалы-ай» әндерін танып, олардың ерекшеліктерін айта білу": "Шинохтани Естай Беркинбайули ва сурудҳои «Қусни-Қорлан», «Қоғали-ай» ва тавонистани гуфтани хусусиятҳои онҳо",
"Естай Беркінбайұлы": "Естай Беркинбайули",
"Естай (1874–1946) — композитор, ақын-әнші. Ол Павлодар өңірінде дүниеге келген.": "Естай (1874–1946) — оҳангсоз, шоир ва сароянда. Ӯ дар ноҳияи Павлодар таваллуд шудааст.",
"Естайдың әндері": "Сурудҳои Естай",
"«Майда қоңыр» және «Дүние» — Естайдың қазақ халқына белгілі әндері. «Құсни-Қорлан» әні бүкіл әлемге танымал.": "«Майда қонир» ва «Дуние» — сурудҳои Естай, ки барои халқи қазоқ маълум аст. Суруди «Қусни-Қорлан» дар тамоми ҷаҳон машҳур аст.",
"«Құсни-Қорлан» әні": "Суруди «Қусни-Қорлан»",
"Өлеңі мен әнін Естай жазған. Ән сұлулықты дәріптейді және қазақтың ең үздік әндерінің бірі.": "Шеър ва оҳангашро Естай навиштааст. Суруд зебоиро ситоиш мекунад ва яке аз беҳтарин сурудҳои қазоқист.",
"Ән қалай туды?": "Суруд чӣ тавр ба вуҷуд омад?",
"Естай 20 жасында Маралды ауылындағы тойда Сұлтан бидің Құсни және Қорлан есімді қыздарын көріп, олардың сұлулығына таңғалып, есімдерін әнге қосқан.": "Естай дар 20-солагӣ дар тӯйи деҳаи Маралди духтарони Султон бий — Қусни ва Қорланро дида, аз зебоии онҳо ҳайрон шуда, номҳояшонро ба суруд даровардааст.",
"«Қоғалы-ай» және сал, сері": "«Қоғали-ай» ва сал, сери",
"«Қоғалы-ай» — ел арасына кең тараған қазақтың халық әні. Естай — Біржан сал мен Ақан серінің өнерін жалғастырушы ірі тұлға.": "«Қоғали-ай» — суруди халқии қазоқӣ, ки дар миёни мардум васеъ паҳн шудааст. Естай — шахсияти бузург, ки санъати Бирҷон сал ва Ақан сериро идома додааст.",
