"Симфониялық оркестрдің аспаптар топтарын ажырату және аспаптарды атау": "Фарқ кардани гурӯҳҳои асбобҳои оркестри симфонӣ ва номбар кардани асбобҳо",
"Симфониялық оркестр": "Оркестри симфонӣ",
"Симфониялық оркестр алғаш рет 18-ғасырда Еуропада пайда болды. Оның құрамы ішекті-ысқышты, үрлемелі және соқпалы аспаптардан тұрады.": "Оркестри симфонӣ бори аввал дар асри 18 дар Аврупо пайдо шуд. Таркиби он аз асбобҳои тордори камонӣ, бодӣ ва зарбӣ иборат аст.",
"Ішекті-ысқышты және үрлемелі-ағаш": "Тордори камонӣ ва бодии чӯбин",
"Ішекті-ысқышты топқа скрипка, альт, виолончель, контрабас кіреді. Үрлемелі-ағаш топта флейта, гобой, кларнет, фагот бар.": "Ба гурӯҳи тордори камонӣ скрипка, альт, виолончел, контрабас дохил мешаванд. Дар гурӯҳи бодии чӯбин флейта, гобой, кларнет, фагот ҳастанд.",
"Үрлемелі-мыс және шулы-ұрмалы": "Бодии мисин ва садодор-зарбӣ",
"Үрлемелі-мыс топқа валторна, труба, тромбон, туба жатады. Шулы-ұрмалы топта барабан, дауылпаз, үшбұрыш, тарелка, литавра, қоңырау, ксилофон сияқты аспаптар бар.": "Ба гурӯҳи бодии мисин валторна, труба, тромбон, туба тааллуқ доранд. Дар гурӯҳи садодор-зарбӣ асбобҳое чун баробан, литавра, секунҷа, тарелка, занг ва ксилофон ҳастанд.",
"Клавишті және қосымша топ": "Клавишӣ ва гурӯҳи иловагӣ",
"Клавишті аспаптарға рояль, орган, клавесин, клавикорд жатады. Қосымша топқа арфа кіреді.": "Ба асбобҳои клавишӣ роял, орган, клавесин, клавикорд тааллуқ доранд. Ба гурӯҳи иловагӣ арфа дохил мешавад.",
"«Сарыжайлау» күйі": "Куйи «Сарыжайлау»",
"«Сарыжайлау» — Тәттімбеттің күйі. Оны симфониялық оркестр де, қазақ халық аспаптары оркестрі де орындай алады. Халық аспаптары оркестрінде қобыз, домбыра, сазсырнай, жетіген бар.": "«Сарыжайлау» — куйи Таттимбет. Онро ҳам оркестри симфонӣ ва ҳам оркестри асбобҳои халқии қазоқ иҷро карда метавонад. Дар оркестри асбобҳои халқӣ қобыз, домбыра, сазсырнай, жетиген ҳастанд.",
"Аспапты тобына қарай орналастыр": "Асбобро ба гурӯҳи худ ҷойгир кун",
"Симфониялық оркестрдегі әр аспапты өз тобына қой.": "Ҳар асбоби оркестри симфониро ба гурӯҳи худаш гузор.",
