"Дұрыс. Иә, бұл Тәттімбеттің күйі.": "Дуруст. Ҳа, ин куйи Таттимбет аст.",
"Дұрыс. Дұрыс, алғаш рет Еуропада 18-ғасырда пайда болған.": "Дуруст. Дуруст, бори аввал дар Аврупо дар асри 18 пайдо шудааст.",
"Бұрыс. Скрипка — ішекті-ысқышты аспап.": "Нодуруст. Скрипка — асбоби тордори камонӣ.",
"Дұрыс. Иә, арфа қосымша топта.": "Дуруст. Ҳа, арфа дар гурӯҳи иловагӣ аст.",
"Бұрыс. Қобыз — қазақтың халық аспабы.": "Нодуруст. Қобыз — асбоби халқии қазоқ.",
"Дұрыс. Бұлардың бәрі үрлемелі-ағаш топқа жатады.": "Дуруст. Ҳамаи инҳо ба гурӯҳи бодии чӯбин тааллуқ доранд.",
"Дұрыс. Иә, екеуі де клавишті аспап.": "Дуруст. Ҳа, ҳардуи онҳо асбоби клавишӣ мебошанд.",
"Бұрыс. Олар шулы-ұрмалы аспаптар.": "Нодуруст. Онҳо асбобҳои садодор-зарбӣ мебошанд.",
"Дұрыс. Иә, олар қазақтың ұлттық аспаптары.": "Дуруст. Ҳа, онҳо асбобҳои миллии қазоқ мебошанд.",
"Бұрыс. Тромбон — үрлемелі-мыс аспап.": "Нодуруст. Тромбон — асбоби бодии мисин.",
"Табыңыз: Ішекті-ысқышты": "Ёбед: Тордори камонӣ",
"Табыңыз: Үрлемелі-ағаш": "Ёбед: Бодии чӯбин",
"Табыңыз: Үрлемелі-мыс": "Ёбед: Бодии мисин",
"Табыңыз: Симфониялық оркестр": "Ёбед: Оркестри симфонӣ",
"Табыңыз: Қазақ халық аспаптары оркестрі": "Ёбед: Оркестри асбобҳои халқии қазоқ",
"14-сабақ. Мамандығым — мақтанышым": "Дарс 14. Касби ман — ифтихори ман",
"Мамандығым — мақтанышым": "Касби ман — ифтихори ман",
"Мамандықтың бес түрін ажырату, мамандық таңдауға не керек екенін түсіндіру және «Мамандығым — мақтаным» әні туралы айту.": "Панҷ навъи касбро фарқ кардан, фаҳмонидани он ки барои интихоби касб чӣ лозим аст ва дар бораи суруди «Касби ман — ифтихори ман» нақл кардан.",
"Бақыттың кілті": "Калиди хушбахтӣ",
"Адам бақытты болғысы келеді. Бақыттың бір кілті — өзіңе ұнайтын жақсы мамандық таңдау. Өз ісіне риза адам өмірде де бақытты сезінеді.": "Одам мехоҳад хушбахт бошад. Яке аз калидҳои хушбахтӣ — интихоб кардани касби хуб, ки ба ту писанд аст. Одаме, ки аз кори худ розӣ аст, дар зиндагӣ ҳам худро хушбахт ҳис мекунад.",
"Мамандықтың бес түрі": "Панҷ навъи касб",
"Ғалымдар барлық мамандықты бес түрге бөледі: «Адам — адам», «Адам — белгі жүйесі», «Адам — техника», «Адам — табиғат», «Адам — өнер».": "Олимон тамоми касбҳоро ба панҷ навъ ҷудо мекунанд: «Одам — одам», «Одам — системаи аломатҳо», «Одам — техника», «Одам — табиат», «Одам — санъат».",
"Мамандық таңдағанда": "Ҳангоми интихоби касб",
"Сүйікті ісіңе айналу үшін шын ниет, қалау, қызығушылық, бейімділік және қабілет керек. Ата-ананың ақылы мен тәрбиенің де маңызы бар.": "Барои ба кори дӯстдошта табдил ёфтан нияти самимӣ, хоҳиш, шавқ, майл ва қобилият лозим аст. Маслиҳати падару модар ва тарбия низ аҳамият доранд.",
"Ән «Мамандығым — мақтаным»": "Суруди «Касби ман — ифтихори ман»",
"Бұл әннің сөзін А. Асылбек жазған, әнін Н. Хинков-Айтбаева шығарған. Әнде құрылысшы, дәрігер, мұғалім, аспаз, жүргізуші туралы айтылады. Әр шумақтан кейін қайырма қайталанады.": "Сухани ин сурудро А. Асылбек навиштааст, оҳанги онро Н. Хинков-Айтбаева эҷод кардааст. Дар суруд дар бораи бинокор, табиб, омӯзгор, ошпаз, ронанда гуфта мешавад. Баъд аз ҳар бант сарнағма такрор мешавад.",
"Бір жұмысқа — үш көзқарас": "Ба як кор — се нигоҳ",
"Өте ерте заманда үш жұмысшы бір құрылыста жұмыс істеп жүрген. Үшеуіне де «Не істеп жатырсың?» деп сұрағанда, олар үш түрлі жауап берген. Адамдар өз еңбегіне әртүрлі қарайды.": "Хеле қадим се коргар дар як бинокорӣ кор мекарданд. Вақте аз ҳар се пурсиданд: «Чӣ кор карда истодаӣ?», онҳо се хел ҷавоб доданд. Одамон ба меҳнати худ гуногун менигаранд.",
"Мамандықты тобына орналастыр": "Касбро ба гурӯҳаш ҷойгир кун",
"Әр мамандықты қай топқа жататынын тап.": "Ҳар касбро ёб, ки ба кадом гурӯҳ тааллуқ дорад.",
"Бұл мамандық қай топқа жатады?": "Ин касб ба кадом гурӯҳ тааллуқ дорад?",
