"Бұрыс. Етік тігетін адам — етікші.": "Нодуруст. Одаме, ки мӯза медӯзад — мӯзадӯз.",
"Дұрыс. Әр шумақтан кейін қайырма айтылады.": "Дуруст. Баъд аз ҳар бант сарнағма хонда мешавад.",
"Бұрыс. А. Асылбек — сөзін жазған, әнін Н. Хинков-Айтбаева шығарған.": "Нодуруст. А. Асылбек — сухан навиштааст, оҳангро Н. Хинков-Айтбаева эҷод кардааст.",
"Дұрыс. Әр шумақта бір мамандық туралы айтылады.": "Дуруст. Дар ҳар бант дар бораи як касб гуфта мешавад.",
"Бұрыс. Олар үш түрлі жауап берді.": "Нодуруст. Онҳо се хел ҷавоб доданд.",
"Дұрыс. Көзқарас адамның еңбегіне деген қатынасын көрсетеді.": "Дуруст. Нигоҳ муносибати одамро ба меҳнати ӯ нишон медиҳад.",
"Табыңыз: Адам — адам": "Ёбед: Одам — одам",
"Табыңыз: Адам — техника": "Ёбед: Одам — техника",
"Табыңыз: Адам — өнер": "Ёбед: Одам — санъат",
"Табыңыз: Мамандық атауы": "Ёбед: Номи касб",
"Табыңыз: Мамандық таңдауға керек қасиет": "Ёбед: Хислате, ки барои интихоби касб лозим аст",
"15-сабақ. Музыкант болу — арманым!": "Дарс 15. Орзуи ман — навозанда шудан!",
"Музыкант болу — арманым!": "Орзуи ман — навозанда шудан!",
"Музыкант мамандығының түрлерін атау және олардың не істейтінін түсіндіру.": "Номбар кардани навъҳои касби мусиқӣ ва фаҳмонидани он ки онҳо чӣ кор мекунанд.",
"Мамандық дегеніміз не?": "Касб чист?",
"Мамандық — адамның еңбек әрекетінің, жұмысының негізгі түрі. Ол адамнан белгілі бір дайындықты, білім мен дағдыны талап етеді.": "Касб — навъи асосии фаъолияти меҳнатӣ, кори одам. Он аз одам тайёрии муайян, дониш ва малака талаб мекунад.",
"Музыкант кім?": "Навозанда кист?",
"Музыкант — музыка саласында жұмыс істейтін маман, кәсіби түрде музыкамен шұғылданады. Олар: композитор, дирижёр, әнші, аспапта орындаушы және т.б.": "Навозанда — мутахассисест, ки дар соҳаи мусиқӣ кор мекунад, касбан бо мусиқӣ машғул аст. Онҳо: композитор, дирижёр, овозхон, иҷрогари асбоб ва ғайра.",
"Ертедегі музыка мамандары": "Мутахассисони қадимии мусиқӣ",
"Ата-бабаларымыз мұраға қалдырған әндер мен күйлер, жыр-термелер бізге жетті. Оны жеткізгендер — халықтың өзі және кәсіби мамандар: сал-серілер, әншілер мен күйшілер, жыраулар.": "Суруду куйҳо, жыр-термеҳое, ки бобокалонҳоямон ба мерос гузоштаанд, ба мо расиданд. Онҳоро расонидагон — худи халқ ва мутахассисони касбӣ: сал-сериҳо, овозхонҳо ва куйчиҳо, жырауҳо.",
"Аспаптық музыка": "Мусиқии асбобӣ",
"Аспаптық музыка — арнайы музыкалық аспаптарда орындауға арналған шығарма. Домбыра, қобыз, скрипка, флейта, пианино — осындай аспаптар.": "Мусиқии асбобӣ — асаре, ки барои иҷро бо асбобҳои махсуси мусиқӣ пешбинӣ шудааст. Домбыра, қобыз, скрипка, флейта, пианино — чунин асбобҳоянд.",
"Мамандығым туралы музыкалық әңгіме": "Ҳикояи мусиқӣ дар бораи касби ман",
"Бұл шығарманың музыкасын Н. Хинков-Айтбаева жазған. Онда кішкентай Наргиздің музыкант болу арманы туралы айтылады: ол скрипканың әдемі дауысын естіп, қатты қызығады.": "Мусиқии ин асарро Н. Хинков-Айтбаева навиштааст. Дар он дар бораи орзуи Наргизи хурдсол барои навозанда шудан нақл мешавад: ӯ овози зебои скрипкаро шунида, сахт шавқманд мешавад.",
"Қай аспапта ойнайды?": "Бо кадом асбоб менавозад?",
"Музыкант мамандығын қазақтың халық аспабына немесе басқа аспапқа қарай топтастыр.": "Касби навозандаро аз рӯи он ки бо асбоби халқии қазоқ ё бо асбоби дигар менавозад, гурӯҳбандӣ кун.",
"Қазақтың халық аспабында ойнайды": "Бо асбоби халқии қазоқ менавозад",
