"Бәрі де музыкалық аспаптар.": "Ҳамаашон асбобҳои мусиқӣ мебошанд.",
"Ол скрипканың дауысына қызығып, скрипкашы болуды армандады.": "Ӯ аз овози скрипка шавқманд шуда, орзу кард, ки скрипкачӣ шавад.",
"Дұрыс, ол фортепиано сыныбына барды.": "Дуруст, ӯ ба синфи фортепиано рафт.",
"«Әнші балапан» әнінің әуенін М. Омаров жазған.": "Оҳанги суруди «Аншӣ балапан»-ро М. Омаров навиштааст.",
"Дирижёр музыканттардың орындауын басқарады.": "Дирижёр иҷрои навозандагонро роҳбарӣ мекунад.",
"Дұрыс. Дұрыс, мамандық — адамның жұмысының негізгі түрі.": "Дуруст. Дуруст, касб — навъи асосии кори одам.",
"Бұрыс. Мамандық белгілі бір дайындықты, білім мен дағдыны талап етеді.": "Нодуруст. Касб тайёрии муайян, дониш ва малакаро талаб мекунад.",
"Дұрыс. Олар музыка саласында жұмыс істейтін мамандар.": "Дуруст. Онҳо мутахассисоне мебошанд, ки дар соҳаи мусиқӣ кор мекунанд.",
"Дұрыс. Олар әндер мен жырларды халыққа жеткізген.": "Дуруст. Онҳо суруду жырҳоро ба халқ расониданд.",
"Бұрыс. Аспаптық музыка аспапта орындалады.": "Нодуруст. Мусиқии асбобӣ бо асбоб иҷро мешавад.",
"Дұрыс. Бәрі де музыкалық аспаптар.": "Дуруст. Ҳамаашон асбобҳои мусиқӣ мебошанд.",
"Бұрыс. Ол скрипканың дауысына қызығып, скрипкашы болуды армандады.": "Нодуруст. Ӯ аз овози скрипка шавқманд шуда, орзу кард, ки скрипкачӣ шавад.",
"Дұрыс. Дұрыс, ол фортепиано сыныбына барды.": "Дуруст. Дуруст, ӯ ба синфи фортепиано рафт.",
"Бұрыс. «Әнші балапан» әнінің әуенін М. Омаров жазған.": "Нодуруст. Оҳанги суруди «Аншӣ балапан»-ро М. Омаров навиштааст.",
"Дұрыс. Дирижёр музыканттардың орындауын басқарады.": "Дуруст. Дирижёр иҷрои навозандагонро роҳбарӣ мекунад.",
"Табыңыз: Қазақтың халық аспабында ойнайды": "Ёбед: Бо асбоби халқии қазоқ менавозад",
"Табыңыз: Басқа аспапта ойнайды": "Ёбед: Бо асбоби дигар менавозад",
