"Табыңыз: Қазіргі музыкант мамандығы": "Ёбед: Касби навозандаи имрӯза",
"Табыңыз: Музыкалық аспап": "Ёбед: Асбоби мусиқӣ",
"16-сабақ. Музыкант болғым келеді!": "Дарс 16. Мехоҳам навозанда шавам!",
"Музыкант болғым келеді!": "Мехоҳам навозанда шавам!",
"Музыкамен байланысты мамандықтарды (әнші, биші, домбырашы, композитор) атау және олардың не істейтінін түсіндіру.": "Номбар кардани касбҳои алоқаманд ба мусиқӣ (овозхон, раққос, домбырачӣ, композитор) ва фаҳмонидани он ки онҳо чӣ кор мекунанд.",
"Музыкант": "Навозанда",
"Музыкант — музыка саласында жұмыс істейтін маман. Әнші, домбырашы, композитор — музыкамен айналысатын мамандықтар.": "Навозанда — мутахассисест, ки дар соҳаи мусиқӣ кор мекунад. Овозхон, домбырачӣ, композитор — касбҳое мебошанд, ки бо мусиқӣ машғуланд.",
"Әнші — әнмен шығылданатын музыкант, вокалдық музыканы орындаушы. Ол әнді дауыспен айтады.": "Овозхон — навозандаест, ки бо суруд машғул аст, иҷрогари мусиқии вокалӣ. Ӯ сурудро бо овоз мехонад.",
"Домбырашы — домбыра аспабында ойнайтын музыкант. Ол аспапта ойнап, өнерін көрсетеді.": "Домбырачӣ — навозандаест, ки бо домбыра менавозад. Ӯ бо асбоб навохта, санъати худро нишон медиҳад.",
"Композитор — музыкалық шығармалардың авторы, музыканы шығаратын адам. Латын тілінде бұл сөз «құрастырушы» дегенді білдіреді.": "Композитор — муаллифи асарҳои мусиқӣ, одаме, ки мусиқӣ эҷод мекунад. Ба забони лотинӣ ин калима маънои «ташкилдиҳанда»-ро дорад.",
"Мамандық туралы таныстырылым": "Муаррифӣ дар бораи касб",
"Мамандық туралы айтқанда жалпы түсінікті, мамандықтың маманға қоятын кәсіби талаптарын және осы мамандық иелерін таныстыруға болады. Мұны әнші, биші, домбырашы, композитор туралы жасауға болады.": "Ҳангоми сухан дар бораи касб тасаввуроти умумӣ, талаботи касбии касб ба мутахассис ва соҳибони ин касбро муаррифӣ кардан мумкин аст. Инро дар бораи овозхон, раққос, домбырачӣ, композитор кардан мумкин аст.",
